const express = require('express');
const crypto = require('crypto');
const { Database } = require('better-sqlite3');
const argon2 = require('argon2');

const app = express();
app.use(express.json({ limit: '16kb' }));

const db = new Database(':memory:');
db.pragma('journal_mode = WAL');
db.exec(`
  CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    display_name TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT DEFAULT 'user'
  );
  CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender_id INTEGER NOT NULL,
    recipient_id INTEGER NOT NULL,
    subject TEXT NOT NULL,
    body TEXT NOT NULL,
    created_at INTEGER DEFAULT (unixepoch()),
    FOREIGN KEY (sender_id) REFERENCES users(id),
    FOREIGN KEY (recipient_id) REFERENCES users(id)
  );
  CREATE TABLE api_keys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    key_hash TEXT NOT NULL,
    key_prefix TEXT NOT NULL,
    permissions TEXT NOT NULL DEFAULT 'read',
    FOREIGN KEY (user_id) REFERENCES users(id)
  );
`);

// Security: Input sanitization module
const InputValidator = {
  // Maximum lengths for each field type
  MAX_LENGTHS: {
    username: 32,
    display_name: 64,
    subject: 128,
    body: 4096,
    search_query: 64
  },

  // Allowed character patterns
  PATTERNS: {
    username: /^[a-zA-Z0-9_.-]+$/,
    display_name: /^[\p{L}\p{N}\p{M}\s._'-]+$/u,
    search_query: /^[\p{L}\p{N}\p{M}\s._'-]+$/u
  },

  validateLength(value, fieldType) {
    const maxLen = this.MAX_LENGTHS[fieldType];
    if (!maxLen) return false;
    if (typeof value !== 'string') return false;
    if (value.length === 0 || value.length > maxLen) return false;
    return true;
  },

  validatePattern(value, fieldType) {
    const pattern = this.PATTERNS[fieldType];
    if (!pattern) return true; // No pattern = no restriction
    return pattern.test(value);
  },

  sanitizeForDisplay(value) {
    // Normalize Unicode to prevent homoglyph attacks
    const normalized = value.normalize('NFKC');
    return normalized;
  },

  validateAndSanitize(value, fieldType) {
    if (!this.validateLength(value, fieldType)) {
      return { valid: false, error: `${fieldType} length invalid` };
    }
    if (!this.validatePattern(value, fieldType)) {
      return { valid: false, error: `${fieldType} contains invalid characters` };
    }
    // Sanitize after validation passes
    const sanitized = this.sanitizeForDisplay(value);
    return { valid: true, value: sanitized };
  }
};

// Authentication middleware
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  const token = authHeader.slice(7);
  if (token.length !== 64 || !/^[a-f0-9]+$/.test(token)) {
    return res.status(401).json({ error: 'Invalid token format' });
  }
  const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
  const apiKey = db.prepare('SELECT user_id, permissions FROM api_keys WHERE key_hash = ?').get(tokenHash);
  if (!apiKey) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  req.userId = apiKey.user_id;
  req.permissions = apiKey.permissions;
  next();
}

// User registration
app.post('/api/register', async (req, res) => {
  try {
    const { username, display_name, password } = req.body;

    const usernameResult = InputValidator.validateAndSanitize(username, 'username');
    if (!usernameResult.valid) {
      return res.status(400).json({ error: usernameResult.error });
    }

    const displayResult = InputValidator.validateAndSanitize(display_name, 'display_name');
    if (!displayResult.valid) {
      return res.status(400).json({ error: displayResult.error });
    }

    if (!password || password.length < 8 || password.length > 128) {
      return res.status(400).json({ error: 'Password must be 8-128 characters' });
    }

    const passwordHash = await argon2.hash(password, {
      type: argon2.argon2id,
      memoryCost: 65536,
      timeCost: 3,
      parallelism: 1
    });

    const stmt = db.prepare('INSERT INTO users (username, display_name, password_hash) VALUES (?, ?, ?)');
    const result = stmt.run(usernameResult.value, displayResult.value, passwordHash);

    // Generate API key
    const rawKey = crypto.randomBytes(32).toString('hex');
    const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
    const keyPrefix = rawKey.slice(0, 8);

    db.prepare('INSERT INTO api_keys (user_id, key_hash, key_prefix, permissions) VALUES (?, ?, ?, ?)').run(
      result.lastInsertRowid, keyHash, keyPrefix, 'read,write'
    );

    res.status(201).json({
      id: result.lastInsertRowid,
      username: usernameResult.value,
      display_name: displayResult.value,
      api_key: rawKey
    });
  } catch (err) {
    if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
      return res.status(409).json({ error: 'Username already taken' });
    }
    res.status(500).json({ error: 'Registration failed' });
  }
});

// Search users by display name
app.get('/api/users/search', authenticate, (req, res) => {
  const { q } = req.query;
  if (!q) {
    return res.status(400).json({ error: 'Search query required' });
  }

  const queryResult = InputValidator.validateAndSanitize(q, 'search_query');
  if (!queryResult.valid) {
    return res.status(400).json({ error: queryResult.error });
  }

  // Use parameterized query with the sanitized value
  const users = db.prepare(
    'SELECT id, username, display_name FROM users WHERE display_name LIKE ? LIMIT 20'
  ).all(`%${queryResult.value}%`);

  res.json({ results: users });
});

// Send message
app.post('/api/messages', authenticate, (req, res) => {
  if (!req.permissions.includes('write')) {
    return res.status(403).json({ error: 'Write permission required' });
  }

  const { recipient_id, subject, body } = req.body;

  if (!Number.isInteger(recipient_id) || recipient_id <= 0) {
    return res.status(400).json({ error: 'Invalid recipient' });
  }

  const subjectResult = InputValidator.validateAndSanitize(subject, 'subject');
  if (!subjectResult.valid) {
    return res.status(400).json({ error: subjectResult.error });
  }

  const bodyResult = InputValidator.validateAndSanitize(body, 'body');
  if (!bodyResult.valid) {
    return res.status(400).json({ error: bodyResult.error });
  }

  const recipient = db.prepare('SELECT id FROM users WHERE id = ?').get(recipient_id);
  if (!recipient) {
    return res.status(404).json({ error: 'Recipient not found' });
  }

  const stmt = db.prepare(
    'INSERT INTO messages (sender_id, recipient_id, subject, body) VALUES (?, ?, ?, ?)'
  );
  const result = stmt.run(req.userId, recipient_id, subjectResult.value, bodyResult.value);

  res.status(201).json({ id: result.lastInsertRowid });
});

// Get inbox
app.get('/api/messages/inbox', authenticate, (req, res) => {
  const messages = db.prepare(
    `SELECT m.id, m.subject, m.body, m.created_at, u.display_name as sender_name
     FROM messages m JOIN users u ON m.sender_id = u.id
     WHERE m.recipient_id = ? ORDER BY m.created_at DESC LIMIT 50`
  ).all(req.userId);

  res.json({ messages });
});

app.listen(3000);
module.exports = app;
